	@Test
	void decodedPayloadGrowthDemonstratesTheArrayOnlyAccountingLimit(TestReporter reporter) {
		try (Fixture fixture = new Fixture(BUDGET)) {
			fixture.revision.literalCharacters = 2 * 1024 * 1024;
			LmdbLiteral cold = new LmdbLiteral(fixture.revision, A);
			fixture.responses.put(new Request(A, OBJECT), cold);
			assertThat(fixture.resolve(A, OBJECT)).isSameAs(cold);
			long before = fixture.memo.retainedBytes();
			long version = cold.getSemanticVersion();
			assertThat(cold.retainedLexicalLength()).isNegative();
			cold.init();
			long after = fixture.memo.retainedBytes();
			assertThat(cold.getSemanticVersion()).isEqualTo(version);
			assertThat(cold.retainedLexicalLength()).isEqualTo(fixture.revision.literalCharacters);
			reporter.publishEntry(Map.of("diagnosticOnly", "true", "tableChargeBeforeBytes", Long.toString(before),
					"tableChargeAfterBytes", Long.toString(after), "decodedLabelCharacters",
					Long.toString(cold.retainedLexicalLength()), "interpretation",
					"An entry/table bound is not a retained-payload or heap bound; initialization preserves the version."));
			assertThat(before).as("direct-memo: array charge exists before payload growth").isPositive();
			assertThat(after).isEqualTo(before);
			assertThat(after).isLessThan(cold.retainedLexicalLength());
			assertThat(fixture.memo.find(A, OBJECT)).isSameAs(cold);
		}
	}

