	private static void assertReplacementAfterIdentityMutation(Fixture fixture, Value original) {
		LmdbIRI replacement = new LmdbIRI(fixture.revision, "urn:test:replacement", A);
		fixture.responses.put(new Request(A, OBJECT), replacement);
		Value resolved = fixture.resolve(A, OBJECT);
		assertThat(resolved).as("direct-memo: changed ID or revision invalidates the representative")
				.isSameAs(replacement).isNotSameAs(original);
		assertThat(fixture.resolve(A, OBJECT)).isSameAs(replacement);
		assertThat(fixture.sourceCalls).as("direct-memo: recache after identity rejection").isEqualTo(2L);
	}

	private static WeakReference<Value> admitWithoutOtherOwner(NativeDirectValueMemo memo, FixedRevision revision) {
		Value value = new LmdbIRI(revision, "urn:test:strong-owner", A);
		memo.remember(A, OBJECT, value);
		return new WeakReference<>(value);
	}

	private static void assertStronglyRetained(NativeDirectValueMemo memo, WeakReference<Value> reference) {
		for (int attempt = 0; attempt < 3; attempt++) {
			System.gc();
		}
		assertThat(reference.refersTo(null)).as("direct-memo: a live entry owns its value strongly").isFalse();
		assertThat(memo.find(A, OBJECT)).as("direct-memo: retained entry is usable").isNotNull()
				.isSameAs(reference.get());
	}

	private static long differentMaskSlots(int first, int second) {
		for (long id = 1L; id < 100_000L; id++) {
			if (NativeDirectValueMemo.slot(id, first, NativeDirectValueMemo.INITIAL_CAPACITY)
					!= NativeDirectValueMemo.slot(id, second, NativeDirectValueMemo.INITIAL_CAPACITY)) {
				return id;
			}
		}
		throw new AssertionError("Fixture could not choose independent full-mask slots");
	}

	private static void uniqueLookups(Fixture fixture, int count) {
		for (int index = 0; index < count; index++) {
			long id = 1_000_000L + index;
			assertThat(((LmdbValue) fixture.resolve(id, OBJECT)).getInternalID()).isEqualTo(id);
		}
	}

	private static String lexical(long id, int mask) {
		return "urn:test:value:" + id + ":" + mask;
	}

	private record Request(long id, int mask) {
	}

	private static final class Fixture implements AutoCloseable {
		final LmdbQueryMemoryManager manager;
		final LmdbQueryMemoryManager.QueryLedger ledger;
		final NativeDirectValueMemo memo;
		final FixedRevision revision;
		final Map<Request, Value> responses = new HashMap<>();
		long sourceCalls;

		Fixture(long budget) {
			this(budget, new FixedRevision(11L, null));
		}

		Fixture(long budget, FixedRevision revision) {
			this.revision = revision;
			manager = LmdbQueryMemoryManager.createForTesting(budget, budget);
			ledger = manager.openQuery();
			memo = new NativeDirectValueMemo(ledger);
		}

		Value resolve(long id, int mask) {
			Value value = memo.find(id, mask);
			if (value == null) {
				sourceCalls++;
				value = responses.get(new Request(id, mask));
				if (value == null) {
					value = new LmdbIRI(revision, lexical(id, mask), id);
				}
				memo.remember(id, mask, value);
			}
			return value;
		}

		@Override
		public void close() {
			try {
				memo.close();
			} finally {
				ledger.close();
			}
			assertThat(ledger.usedBytes()).isZero();
			assertThat(manager.usedBytes()).isZero();
		}
	}

	/** Three hot probes and one alternating conflicting key per four requests, at every table size. */
	private static final class Trace {
		final long first;
		final long second;
		final long hot;

		Trace() {
			long[] seen = new long[NativeDirectValueMemo.MAX_CAPACITY];
			long foundFirst = 0L;
			long foundSecond = 0L;
			for (long id = 1L; id <= NativeDirectValueMemo.MAX_CAPACITY * 4L; id++) {
				int slot = NativeDirectValueMemo.slot(id, OBJECT, NativeDirectValueMemo.MAX_CAPACITY);
				if (seen[slot] != 0L) {
					foundFirst = seen[slot];
					foundSecond = id;
					break;
				}
				seen[slot] = id;
			}
			if (foundFirst == 0L) {
				throw new AssertionError("Fixture could not choose conflicting keys");
			}
			first = foundFirst;
			second = foundSecond;
			long candidate = 1L;
			while (NativeDirectValueMemo.slot(candidate, OBJECT, NativeDirectValueMemo.INITIAL_CAPACITY)
					== NativeDirectValueMemo.slot(first, OBJECT, NativeDirectValueMemo.INITIAL_CAPACITY)) {
				candidate++;
			}
			hot = candidate;
		}

		void run(Fixture fixture, int offset, int count) {
			for (int index = offset; index < offset + count; index++) {
				long id = (index & 3) != 3 ? hot : ((index >>> 2) & 1) == 0 ? first : second;
				Value value = fixture.resolve(id, OBJECT);
				assertThat(((LmdbValue) value).getInternalID()).isEqualTo(id);
			}
		}
	}

	/** Real model wrappers retain this explicit test revision; no native store or decoder is opened. */
	private static final class FixedRevision extends ValueStoreRevision.Base {
		final long number;
		final ValueStore owner;
		int initializations;
		int literalCharacters;

		FixedRevision(long number, ValueStore owner) {
			this.number = number;
			this.owner = owner;
		}

		@Override
		public long getRevisionId() {
			return number;
		}

		@Override
		public ValueStore getValueStore() {
			return owner;
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			initializations++;
			if (value instanceof LmdbIRI) {
				value.setFromInitializedValue(new LmdbIRI(this, lexical(id, OBJECT), id));
			} else if (value instanceof LmdbLiteral) {
				String label = literalCharacters == 0 ? "resolved-" + id : "x".repeat(literalCharacters);
				value.setFromInitializedValue(new LmdbLiteral(this, label, id));
			} else {
				throw new AssertionError("Unexpected fixture decode type " + value.getClass());
			}
			return true;
		}
	}
